/**
 * A list of all the event resource types defined in this version of the FHIR specification.
 */
export const EventResourceTypes = {
  /**
   * Item containing charge code(s) associated with the provision of healthcare provider products.
   */
  ChargeItem: event_resource_types_ChargeItem,
  /**
   * Remittance resource.
   */
  ClaimResponse: event_resource_types_ClaimResponse,
  /**
   * A clinical assessment performed when planning treatments and management strategies for a patient.
   */
  ClinicalImpression: event_resource_types_ClinicalImpression,
  /**
   * A record of information transmitted from a sender to a receiver.
   */
  Communication: event_resource_types_Communication,
  /**
   * A set of resources composed into a single coherent clinical statement with clinical attestation.
   */
  Composition: event_resource_types_Composition,
  /**
   * Detailed information about conditions, problems or diagnoses.
   */
  Condition: event_resource_types_Condition,
  /**
   * A healthcare consumer's policy choices to permits or denies recipients or roles to perform actions for specific purposes and periods of time.
   */
  Consent: event_resource_types_Consent,
  /**
   * Insurance or medical plan or a payment agreement.
   */
  Coverage: event_resource_types_Coverage,
  /**
   * Record of use of a device.
   */
  DeviceUseStatement: event_resource_types_DeviceUseStatement,
  /**
   * A Diagnostic report - a combination of request information, atomic results, images, interpretation, as well as formatted reports.
   */
  DiagnosticReport: event_resource_types_DiagnosticReport,
  /**
   * A list that defines a set of documents.
   */
  DocumentManifest: event_resource_types_DocumentManifest,
  /**
   * A reference to a document.
   */
  DocumentReference: event_resource_types_DocumentReference,
  /**
   * An interaction during which services are provided to the patient.
   */
  Encounter: event_resource_types_Encounter,
  /**
   * EnrollmentResponse resource.
   */
  EnrollmentResponse: event_resource_types_EnrollmentResponse,
  /**
   * An association of a Patient with an Organization and  Healthcare Provider(s) for a period of time that the Organization assumes some level of responsibility.
   */
  EpisodeOfCare: event_resource_types_EpisodeOfCare,
  /**
   * Explanation of Benefit resource.
   */
  ExplanationOfBenefit: event_resource_types_ExplanationOfBenefit,
  /**
   * Information about patient's relatives, relevant for patient.
   */
  FamilyMemberHistory: event_resource_types_FamilyMemberHistory,
  /**
   * The formal response to a guidance request.
   */
  GuidanceResponse: event_resource_types_GuidanceResponse,
  /**
   * A set of images produced in single study (one or more series of references images).
   */
  ImagingStudy: event_resource_types_ImagingStudy,
  /**
   * Immunization event information.
   */
  Immunization: event_resource_types_Immunization,
  /**
   * Results of a measure evaluation.
   */
  MeasureReport: event_resource_types_MeasureReport,
  /**
   * A photo, video, or audio recording acquired or used in healthcare. The actual content may be inline or provided by direct reference.
   */
  Media: event_resource_types_Media,
  /**
   * Administration of medication to a patient.
   */
  MedicationAdministration: event_resource_types_MedicationAdministration,
  /**
   * Dispensing a medication to a named patient.
   */
  MedicationDispense: event_resource_types_MedicationDispense,
  /**
   * Record of medication being taken by a patient.
   */
  MedicationStatement: event_resource_types_MedicationStatement,
  /**
   * Measurements and simple assertions.
   */
  Observation: event_resource_types_Observation,
  /**
   * PaymentNotice request.
   */
  PaymentNotice: event_resource_types_PaymentNotice,
  /**
   * PaymentReconciliation resource.
   */
  PaymentReconciliation: event_resource_types_PaymentReconciliation,
  /**
   * An action that is being or was performed on a patient.
   */
  Procedure: event_resource_types_Procedure,
  /**
   * ProcessResponse resource.
   */
  ProcessResponse: event_resource_types_ProcessResponse,
  /**
   * A structured set of questions and their answers.
   */
  QuestionnaireResponse: event_resource_types_QuestionnaireResponse,
  /**
   * Potential outcomes for a subject with likelihood.
   */
  RiskAssessment: event_resource_types_RiskAssessment,
  /**
   * Delivery of bulk Supplies.
   */
  SupplyDelivery: event_resource_types_SupplyDelivery,
  /**
   * A task to be performed.
   */
  Task: event_resource_types_Task,
};
