const event_status_Unknown: Coding = {
  code: 'unknown',
  display: 'Unknown',
  system: 'http://hl7.org/fhir/event-status',
};
/**
 * Codes identifying the lifecycle stage of an event.
 */
export const EventStatus = {
  /**
   * The event has now concluded.
   */
  Completed: event_status_Completed,
  /**
   * This electronic record should never have existed, though it is possible that real-world decisions were based on it.  (If real-world activity has occurred, the status should be "stopped" rather than "entered-in-error".).
   */
  EnteredInError: event_status_EnteredInError,
  /**
   * The event is currently occurring.
   */
  InProgress: event_status_InProgress,
  /**
   * The event was terminated prior to any activity beyond preparation.  I.e. The 'main' activity has not yet begun.  The boundary between preparatory and the 'main' activity is context-specific.
   */
  NotDone: event_status_NotDone,
  /**
   * The event has been temporarily stopped but is expected to resume in the future.
   */
  OnHold: event_status_OnHold,
  /**
   * The core event has not started yet, but some staging activities have begun (e.g. surgical suite preparation).  Preparation stages may be tracked for billing purposes.
   */
  Preparation: event_status_Preparation,
  /**
   * The event was terminated prior to the full completion of the intended activity but after at least some of the 'main' activity (beyond preparation) has occurred.
   */
  Stopped: event_status_Stopped,
  /**
   * The authoring/source system does not know which of the status values currently applies for this event.  Note: This concept is not to be used for "other" - one of the listed statuses is presumed to apply,  but the authoring/source system does not know which.
   */
  Unknown: event_status_Unknown,
};
