/**
 * A list of all the request resource types defined in this version of the FHIR specification.
 */
export const RequestResourceTypes = {
  /**
   * A booking of a healthcare event among patient(s), practitioner(s), related person(s) and/or device(s) for a specific date/time. This may result in one or more Encounter(s).
   */
  Appointment: request_resource_types_Appointment,
  /**
   * A reply to an appointment request for a patient and/or practitioner(s), such as a confirmation or rejection.
   */
  AppointmentResponse: request_resource_types_AppointmentResponse,
  /**
   * Healthcare plan for patient or group.
   */
  CarePlan: request_resource_types_CarePlan,
  /**
   * Claim, Pre-determination or Pre-authorization.
   */
  Claim: request_resource_types_Claim,
  /**
   * A request for information to be sent to a receiver.
   */
  CommunicationRequest: request_resource_types_CommunicationRequest,
  /**
   * Legal Agreement.
   */
  Contract: request_resource_types_Contract,
  /**
   * Medical device request.
   */
  DeviceRequest: request_resource_types_DeviceRequest,
  /**
   * Enrollment request.
   */
  EnrollmentRequest: request_resource_types_EnrollmentRequest,
  /**
   * Guidance or advice relating to an immunization.
   */
  ImmunizationRecommendation: request_resource_types_ImmunizationRecommendation,
  /**
   * Ordering of medication for patient or group.
   */
  MedicationRequest: request_resource_types_MedicationRequest,
  /**
   * Diet, formula or nutritional supplement request.
   */
  NutritionOrder: request_resource_types_NutritionOrder,
  /**
   * A record of a request for service such as diagnostic investigations, treatments, or operations to be performed.
   */
  ServiceRequest: request_resource_types_ServiceRequest,
  /**
   * Request for a medication, substance or device.
   */
  SupplyRequest: request_resource_types_SupplyRequest,
  /**
   * A task to be performed.
   */
  Task: request_resource_types_Task,
  /**
   * Prescription for vision correction products for a patient.
   */
  VisionPrescription: request_resource_types_VisionPrescription,
};
