/**
 * The free/busy status of the slot.
 */
export const Slotstatus = {
  /**
   * Indicates that the time interval is busy because one  or more events have been scheduled for that interval.
   */
  Busy: slotstatus_Busy,
  /**
   * Indicates that the time interval is busy because one or more events have been tentatively scheduled for that interval.
   */
  BusyTentative: slotstatus_BusyTentative,
  /**
   * Indicates that the time interval is busy and that the interval cannot be scheduled.
   */
  BusyUnavailable: slotstatus_BusyUnavailable,
  /**
   * This instance should not have been part of this patient's medical record.
   */
  EnteredInError: slotstatus_EnteredInError,
  /**
   * Indicates that the time interval is free for scheduling.
   */
  Free: slotstatus_Free,
};
