const v3_substanceAdminSubstitution_ActSubstanceAdminSubstitutionCode: Coding = {
  code: '_ActSubstanceAdminSubstitutionCode',
  display: 'ActSubstanceAdminSubstitutionCode',
  system: 'http://terminology.hl7.org/CodeSystem/v3-substanceAdminSubstitution',
};
/**
 *  Identifies what sort of change is permitted or has occurred between the therapy that was ordered and the therapy that was/will be provided.
 */
export const V3SubstanceAdminSubstitution = {
  /**
   * Description: Substitution occurred or is permitted with another product that may potentially have different ingredients, but having the same biological and therapeutic effects.
   */
  ActSubstanceAdminSubstitutionCode: v3_substanceAdminSubstitution_ActSubstanceAdminSubstitutionCode,
  /**
   * Description:
   *
   *
   *                         Substitution occurred or is permitted between equivalent Brands but not Generics
   *
   *
   *                            Examples:
   *
   *
   *
   *                            Zestril  for Prinivil
   *                            Coumadin for Jantoven
   */
  BrandComposition: v3_substanceAdminSubstitution_BrandComposition,
  /**
   * Description: Substitution occurred or is permitted with another bioequivalent and therapeutically equivalent product.
   */
  Equivalent: v3_substanceAdminSubstitution_Equivalent,
  /**
   * Description:
   *
   *
   *                         Substitution occurred or is permitted with another product that is a:
   *
   *
   *                            pharmaceutical alternative containing the same active ingredient but is formulated with different salt, ester
   *                            pharmaceutical equivalent that has the same active ingredient, strength, dosage form and route of administration
   *
   *
   *                            Examples:
   *
   *
   *
   *
   *                               Pharmaceutical alternative: Erythromycin Ethylsuccinate for Erythromycin Stearate
   *
   *                               Pharmaceutical equivalent: Lisonpril for Zestril
   */
  EquivalentComposition: v3_substanceAdminSubstitution_EquivalentComposition,
  /**
   * Description: This substitution was performed or is permitted based on formulary guidelines.
   */
  Formulary: v3_substanceAdminSubstitution_Formulary,
  /**
   * Description: Substitution occurred or is permitted between equivalent Generics but not Brands
   *
   *
   *                            Examples:
   *
   *
   *
   *                            Lisnopril (Lupin Corp) for Lisnopril (Wockhardt Corp)
   */
  GenericComposition: v3_substanceAdminSubstitution_GenericComposition,
  /**
   * No substitution occurred or is permitted.
   */
  None: v3_substanceAdminSubstitution_None,
  /**
   * Description: Substitution occurred or is permitted between therapeutically equivalent Brands but not Generics
   * >
   *                            Examples:
   *
   *
   *
   *                            Zantac for Tagamet
   */
  TherapeuticBrand: v3_substanceAdminSubstitution_TherapeuticBrand,
  /**
   * Description: Substitution occurred or is permitted with another product having the same therapeutic objective and safety profile.
   *
   *
   *                            Examples:
   *
   *
   *
   *                            ranitidine for Tagamet
   */
  TherapeuticAlternative: v3_substanceAdminSubstitution_TherapeuticAlternative,
  /**
   * Description: Substitution occurred or is permitted between therapeutically equivalent Generics but not Brands
   * >
   *                            Examples:
   *
   *
   *
   *                            Ranitidine  for cimetidine
   */
  TherapeuticGeneric: v3_substanceAdminSubstitution_TherapeuticGeneric,
};
/**
 * No Description Provided
 */
export const V3SubstanceAdminSubstitutionReason = {
  /**
   * Indicates that the decision to substitute or to not substitute was driven by a desire to maintain consistency with a pre-existing therapy.  I.e. The performer provided the same item/service as had been previously provided rather than providing exactly what was ordered, or rather than substituting with a lower-cost equivalent.
   */
  ContinuingTherapy: v3_ActReason_ContinuingTherapy,
  /**
   * Indicates that the decision to substitute or to not substitute was driven by a policy expressed within the formulary.
   */
  FormularyPolicy: v3_ActReason_FormularyPolicy,
  /**
   * In the case of 'substitution', indicates that the substitution occurred because the ordered item was not in stock.  In the case of 'no substitution', indicates that a cheaper equivalent was not substituted because it was not in stock.
   */
  OutOfStock: v3_ActReason_OutOfStock,
  /**
   * Indicates that the decision to substitute or to not substitute was driven by a jurisdictional regulatory requirement mandating or prohibiting substitution.
   */
  RegulatoryRequirement: v3_ActReason_RegulatoryRequirement,
};
